    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(
    new OpenAIChatClient(new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId)));

builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

// Define the tools available to the agent
var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            Console.WriteLine($"  [Searching web for: \"{query}\"]");
            // Simulated web search — replace with a real search API (e.g., Bing Search)
            return query.ToLowerInvariant() switch
            {
                var q when q.Contains("quantum computing") =>
                    """
                    1. Quantum computers use qubits that can exist in superposition, enabling parallel computation.
                    2. Google achieved quantum supremacy in 2019 with their Sycamore processor (53 qubits).
                    3. IBM launched a 1,121-qubit processor (Condor) in 2023 and targets error-corrected systems by 2029.
                    4. Key applications include cryptography, drug discovery, optimization, and materials science.
                    5. Current challenges: decoherence, error rates, and extreme cooling requirements (near absolute zero).
                    """,
                var q when q.Contains("application") || q.Contains("use case") =>
                    """
                    1. Drug discovery: simulating molecular interactions at quantum scale.
                    2. Financial modeling: portfolio optimization and risk analysis.
                    3. Cryptography: Shor's algorithm threatens RSA; post-quantum crypto is being standardized.
                    4. Climate modeling: simulating complex atmospheric and ocean systems.
                    5. Supply chain: solving combinatorial optimization problems exponentially faster.
                    """,
                _ =>
                    $"Search results for '{query}': Found general information about the topic. " +
                    "The topic is actively researched with recent developments in 2024-2025."
            };
        },
        "search_web",
        "Searches the web for information about a topic. Returns relevant search results."),

    AIFunctionFactory.Create(
        ([Description("A concise title for the note")] string title,
         [Description("The content/body of the note")] string content) =>
        {
            noteService.AddNote(title, content);
            Console.WriteLine($"  [Note saved: \"{title}\"]");
            return $"Note '{title}' saved successfully.";
        },
        "take_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = noteService.GetAllNotes();
            return notes.Count == 0
                ? "No notes have been taken yet."
                : string.Join("\n\n", notes.Select((n, i) => $"Note {i + 1} - {n.Title}:\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all research notes taken so far."),
};

// Configure the agent with tools and instructions
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly by:
        1) Searching the web for relevant information using multiple queries from different angles.
        2) Taking notes on key findings as you discover them.
        3) After gathering enough information, reviewing your notes and providing a comprehensive summary.
        Always search from multiple angles and take notes before summarizing.
        """,
    tools: tools);

// Run the agent
var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";
Console.WriteLine($"Researching topic: \"{topic}\"\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic and provide a comprehensive summary: {topic}")
};

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(messages, session);

Console.WriteLine("\n========== RESEARCH SUMMARY ==========\n");
Console.WriteLine(response.Text ?? "No summary was generated.");

if (noteService.GetAllNotes().Count > 0)
{
    Console.WriteLine("\n========== RESEARCH NOTES ==========\n");
    foreach (var note in noteService.GetAllNotes())
    {
        Console.WriteLine($"## {note.Title}");
        Console.WriteLine(note.Content);
        Console.WriteLine();
    }
}

